const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '木塞受力示意' },
      { kind: 'text', payload: '拉力 F' },
      { kind: 'text', payload: '瓶内气压与摩擦的合力' }
    ];
  },
  render: function (input, metrics) {
    var sdk = globalThis.visualSdk;
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var s = Math.min(W / 360, H / 280);
    var ox = (W - 360 * s) / 2;
    var oy = (H - 280 * s) / 2;
    function P(x, y) { return [ox + x * s, oy + y * s]; }
    function poly(pts) {
      return sdk.polyline(pts.map(function (p) { return P(p[0], p[1]); }));
    }
    function arrow(x1, y1, x2, y2) {
      var a = P(x1, y1);
      var b = P(x2, y2);
      return sdk.arrow(a[0], a[1], b[0], b[1], {});
    }
    var cx = 150;
    var bottle = poly([[cx - 28, 72], [cx - 28, 145], [cx - 72, 178], [cx - 72, 244], [cx + 72, 244], [cx + 72, 178], [cx + 28, 145], [cx + 28, 72]]);
    var cork = poly([[cx - 22, 60], [cx + 22, 60], [cx + 22, 104], [cx - 22, 104], [cx - 22, 60]]);
    var pull = arrow(cx, 58, cx, 20);
    var down = arrow(cx, 110, cx, 172);
    var t1 = P(16, 26);
    var t2 = P(160, 44);
    var t3 = P(cx, 206);
    return {
      schemaVersion: 1,
      sceneId: 'cork-force',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'bottle', commands: bottle },
        { id: 'cork', commands: cork },
        { id: 'pull', commands: pull },
        { id: 'down', commands: down }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'bottle', stroke: '#26354a', strokeWidth: 2, fill: '#eef3fa' },
          { type: 'path', pathId: 'cork', stroke: '#8a6d3b', strokeWidth: 2, fill: '#e6d2ae' },
          { type: 'path', pathId: 'pull', stroke: '#c0392b', strokeWidth: 2 },
          { type: 'path', pathId: 'down', stroke: '#1d6fb8', strokeWidth: 2 },
          { type: 'label', x: t1[0], y: t1[1], text: '木塞受力示意', fontSize: 14 * s, anchor: 'start', fill: '#1f2d3d' },
          { type: 'label', x: t2[0], y: t2[1], text: '拉力 F', fontSize: 13 * s, anchor: 'start', fill: '#c0392b' },
          { type: 'label', x: t3[0], y: t3[1], text: '瓶内气压与摩擦的合力', fontSize: 12 * s, anchor: 'middle', fill: '#1d6fb8' }
        ]
      }
    };
  }
};
